/** Integra el registro real de diez clientes, edición, suspensión y alta de vehículo sin dejar datos de desarrollo. */
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:registroe2e;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password="}) @Transactional @Rollback class RegistroClientesE2ETest {
 @Autowired ClienteRegistrationFacade clientes; @Autowired VehiculoFacade vehiculos; @Autowired ClienteRepository clienteRepo; @Autowired TallerRepository tallerRepo; @Autowired UserRepository usuarioRepo; @Autowired RoleRepository rolRepo; @Autowired JdbcTemplate jdbc;
 final List<Path> fotos=new ArrayList<>(); Taller norte,centro; UsernamePasswordAuthenticationToken admin,recepcion;
 /** Inserta tres direcciones SEPOMEX reales y dos talleres aislados para el flujo completo. */ @BeforeEach void preparar() throws Exception {jdbc.update("insert into sepomex_asentamientos(codigo_postal,colonia,tipo_asentamiento,municipio,estado,c_estado,c_mnpio) values('03100','Del Valle Centro','Colonia','Benito Juárez','Ciudad de México','09','014')");jdbc.update("insert into sepomex_asentamientos(codigo_postal,colonia,tipo_asentamiento,municipio,estado,c_estado,c_mnpio) values('44100','Centro','Colonia','Guadalajara','Jalisco','14','039')");jdbc.update("insert into sepomex_asentamientos(codigo_postal,colonia,tipo_asentamiento,municipio,estado,c_estado,c_mnpio) values('64000','Centro','Colonia','Monterrey','Nuevo León','19','039')");norte=taller("Taller Horizonte Norte","THN260101AB1","norte");centro=taller("Taller Horizonte Centro","THC260101AB1","centro");Role ra=rolRepo.findByNombre(RoleName.ADMINISTRADOR_SISTEMA).orElseThrow(),rr=rolRepo.findByNombre(RoleName.RECEPCIONISTA).orElseThrow();User ua=usuario("admin.e2e@taller.local",ra,norte),ur=usuario("recepcion.e2e@taller.local",rr,norte);admin=new UsernamePasswordAuthenticationToken(ua.email,"",List.of(new SimpleGrantedAuthority("ROLE_ADMINISTRADOR_SISTEMA")));recepcion=new UsernamePasswordAuthenticationToken(ur.email,"",List.of(new SimpleGrantedAuthority("ROLE_RECEPCIONISTA")));}
/** Registra diez personas, verifica duplicados y cubre el ciclo suspensión → reactivación → vehículo. */ @Test void flujoCompletoDeDiezClientes() throws Exception {List<Registro> datos=datos();List<Long> ids=new ArrayList<>();for(int i=0;i<datos.size();i++){var respuesta=clientes.registrar(datos.get(i),foto(),"e2e-cliente-"+i,admin);ids.add(respuesta.id());}assertEquals(10,ids.size());var guardados=clienteRepo.findAllById(ids);assertEquals(10,guardados.size());assertTrue(guardados.stream().allMatch(c->!c.isDeleted&&c.status!=null&&StatusValues.ACTIVO.equals(c.status.strValor)));ResponseStatusException duplicado=assertThrows(ResponseStatusException.class,()->clientes.registrar(datos.get(0),foto(),"e2e-duplicado",admin));assertEquals(409,duplicado.getStatusCode().value());assertEquals(10,clienteRepo.count());editar(ids.get(0),datos.get(0));editar(ids.get(1),datos.get(1));clientes.suspender(ids.get(2),norte.id,admin);assertTrue(clienteRepo.findById(ids.get(2)).orElseThrow().isDeleted);assertTrue(clientes.consultar(0,10,"",norte.id,"nombreCompleto","asc",admin).clientes().stream().noneMatch(x->x.id().equals(ids.get(2))));assertTrue(clientes.consultarSuspension(0,10,"",norte.id,"nombreCompleto","asc",admin).clientes().stream().anyMatch(x->x.id().equals(ids.get(2))));ResponseStatusException suspendido=assertThrows(ResponseStatusException.class,()->vehiculos.registrar(new VehiculoDtos.Registro(ids.get(2),"1HGCM82633A004352","abc-12","Honda","Accord",2025,"LX","Gris",null),recepcion));assertEquals(409,suspendido.getStatusCode().value());assertEquals("Cliente reactivado",clientes.reactivar(ids.get(2),norte.id,admin).mensaje());Cliente reactivado=clienteRepo.findById(ids.get(2)).orElseThrow();assertFalse(reactivado.isDeleted);assertEquals(StatusValues.ACTIVO,reactivado.status.strValor);editar(ids.get(2),datos.get(2));assertEquals("Vehículo Activo",vehiculos.registrar(new VehiculoDtos.Registro(ids.get(2),"1HGCM82633A004354","abc-14","Honda","Accord",2025,"LX","Gris",1200L),recepcion).mensaje());var alta=vehiculos.registrar(new VehiculoDtos.Registro(ids.get(0),"1HGCM82633A004353","abc-13","Honda","Accord",2025,"LX","Gris",1200L),recepcion);assertEquals("Vehículo Activo",alta.mensaje());}
 /** Actualiza un dato no duplicado mediante el flujo real de edición. */ private void editar(Long id,Registro r){var d=new com.taller.portal.dto.AdministracionClienteDtos.Edicion(r.nombreCompleto(),r.contactoAlternativo(),r.edad(),r.fechaNacimiento(),r.telefonoPersonal(),r.telefonoTrabajo(),r.email(),r.emailTrabajo(),r.direccion(),r.tallerId());assertEquals(id,clientes.editar(id,d,r.tallerId(),admin).id());}
 /** Construye los diez datos diversos con edades calculadas y tres municipios SEPOMEX insertados. */ private List<Registro> datos(){String[][] p={{"María Fernanda López Ruiz","Elena Ruiz","1984-03-14","5510010001","5510020001","maria.lopez@familia.mx","maria.lopez@oficina.mx","03100","Del Valle Centro","Benito Juárez","Ciudad de México"},{"José Antonio Hernández Soto","Lucía Soto","1972-07-09","3310010002","3310020002","jose.hernandez@correo.mx","","44100","Centro","Guadalajara","Jalisco"},{"Ana Sofía Martínez León","Pedro León","1991-11-22","8110010003","8110020003","ana.martinez@hogar.mx","ana.martinez@empresa.mx","64000","Centro","Monterrey","Nuevo León"},{"Carlos Eduardo Ramírez Vega","Patricia Vega","1968-01-30","5510010004","5510020004","carlos.ramirez@correo.mx","","03100","Del Valle Centro","Benito Juárez","Ciudad de México"},{"Verónica García Mora","Daniel Mora","1988-05-18","3310010005","3310020005","veronica.garcia@familia.mx","veronica.garcia@trabajo.mx","44100","Centro","Guadalajara","Jalisco"},{"Miguel Ángel Torres Díaz","Sandra Díaz","1975-09-02","8110010006","8110020006","miguel.torres@correo.mx","","64000","Centro","Monterrey","Nuevo León"},{"Laura Beatriz Sánchez Cruz","Jorge Cruz","1996-12-11","5510010007","5510020007","laura.sanchez@hogar.mx","laura.sanchez@empresa.mx","03100","Del Valle Centro","Benito Juárez","Ciudad de México"},{"Roberto Silva Pineda","Adriana Pineda","1963-04-25","3310010008","3310020008","roberto.silva@correo.mx","","44100","Centro","Guadalajara","Jalisco"},{"Gabriela Flores Campos","Héctor Campos","2001-08-16","8110010009","8110020009","gabriela.flores@familia.mx","gabriela.flores@trabajo.mx","64000","Centro","Monterrey","Nuevo León"},{"Daniel Alberto Ortega Núñez","Mónica Núñez","1980-06-07","5510010010","5510020010","daniel.ortega@correo.mx","","03100","Del Valle Centro","Benito Juárez","Ciudad de México"}};List<Registro> r=new ArrayList<>();for(int i=0;i<p.length;i++){LocalDate f=LocalDate.parse(p[i][2]);int edad=Period.between(f,LocalDate.now()).getYears();r.add(new Registro(p[i][0],p[i][1],edad,f,p[i][3],p[i][4],p[i][5],p[i][6],new Direccion("Avenida del Servicio "+(20+i),p[i][8],p[i][9],p[i][10],p[i][7]),i<5?norte.id:centro.id));}return r;}
 /** Crea taller aislado con campos obligatorios válidos. */ private Taller taller(String nombre,String rfc,String llave){Taller t=new Taller();t.nombre=nombre;t.nombreNormalizado=nombre.toUpperCase(Locale.ROOT);t.razonSocial=nombre+" Servicios";t.razonSocialNormalizada=t.razonSocial.toUpperCase(Locale.ROOT);t.rfc=rfc;t.telefono="555555"+("0000"+llave.hashCode()).replace('-','0').substring(0,4);t.email=llave+"@taller.local";t.calle="Avenida Central 100";t.colonia="Del Valle Centro";t.municipio="Benito Juárez";t.estado="Ciudad de México";t.codigoPostal="03100";t.idempotencyKey="e2e-"+llave;return tallerRepo.save(t);}
 /** Crea usuario activo necesario para auditoría y alcance del vehículo. */ private User usuario(String email,Role rol,Taller taller){User u=new User();u.nombre="Operador E2E";u.email=email;u.celular="559999"+(email.startsWith("admin")?"0001":"0002");u.passwordHash="hash";u.rol=rol;u.taller=taller;u.activo=true;u.emailVerificado=true;return usuarioRepo.save(u);}
 /** Genera una imagen PNG válida para ejecutar el mismo validador de fotografía. */ private MockMultipartFile foto() throws IOException {BufferedImage im=new BufferedImage(2,2,BufferedImage.TYPE_INT_RGB);ByteArrayOutputStream out=new ByteArrayOutputStream();ImageIO.write(im,"png",out);return new MockMultipartFile("fotografia","cliente.png","image/png",out.toByteArray());}
}
